    a, b = 0, 1
    fib_sequence: list[int] = []

    # Generate the Fibonacci sequence until we have enough numbers.
    while len(fib_sequence) < n:
        fib_sequence.append(b)
        # Update the next number in the sequence.
        a, b = b, a + b

    return fib_sequence

